# checking code, ignoring message text entirely
if error["code"] == "not_found":
    handle_missing_resource()

# a shared helper used across many tools
def invalid_arguments_error(field):
    return {"code": "invalid_arguments", "message": f"{field} is required", "data": {"field": field}}

def handle_error(error):
    if error["code"] == "invalid_arguments":
        return "ask_model_to_retry_with_valid_input"
    if error["code"] == "internal_error":
        return "retry_after_delay"
    if error["code"] == "unauthorized":
        return "do_not_retry"
    return "log_and_surface_to_user"

# only retrying errors known to be safe
SAFE_TO_RETRY = {"internal_error", "timeout"}
if error["code"] in SAFE_TO_RETRY:
    retry()
